     #[arg(long = "__internal-daemon-child", hide = true)]
     pub(crate) internal_daemon_child: bool,
 }

 impl ForemanStartArgs {
     pub(crate) fn mode(&self) -> Option<ForemanStartMode> {
         if self.attached {
             Some(ForemanStartMode::Attached)
