     printf '## Verdict\naccept\n'
     ;;
   *)
     printf 'ok'
     ;;
 esac
 "#,
     )?;
     write_executable(
         &bin_dir.join("codex"),
         r#"#!/bin/sh
 printf '## Verdict\naccept\n'
 "#,
     )?;
     Ok(bin_dir)
 }

